"OLAYLAR_DUNYA_AVRUPA2:0378-01-01:0":{"b": ["معركة أدريانوبل: القوط يهزمون فالنس، ويموت الإمبراطور", "3e6e3307"], "d": ["هزم القوط بقيادة فريتيغرن إمبراطور الشرق فالنس في تراقيا قرب أدريانوبل؛ وجُرح فالنس ومات.", "124cd050"]},
"OLAYLAR_DUNYA_AVRUPA2:0437-01-01:0":{"b": ["أيتيوس يهزم مملكة البورغونديين؛ ومقتل الملك غونديكار", "55e4c92e"], "d": ["هزم أيتيوس البورغونديين الذين دخلوا بلجيكا الأولى؛ وسقط الملك غونديكار وانتهت أولى ممالك البورغونديين على الراين.", "ffadfcb5"]},
"OLAYLAR_DUNYA_AVRUPA2:0443-01-01:0":{"b": ["البورغونديون يستقرون في سابوديا بإذن روما", "9bd1ce5d"], "d": ["أُسكن البورغونديون الناجون في سابوديا بصفتهم فيدراتي؛ وكانت نواة مملكة البورغونديين اللاحقة.", "775c0cfa"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0504-01-01:0":{"b": ["معركة أريكيا: هزيمة الأتروسكيين على يد أريستوديموس القومي", "a019f90f"], "d": ["أوقف أريستوديموس القومي، مع اللاتين، تقدم الأتروسكيين؛ وانتهت سيطرة الأتروسكيين على لاتيوم.", "9c00bf17"]},
